const MODEL = 'gemini-3.5-flash';   // غيّر الموديل من هون عند الحاجة
const LESSONS = [
  'ما هو n8n ولماذا هو من أقوى أدوات الأتمتة',
  'تثبيت n8n: السحابة مقابل الاستضافة الذاتية',
  'واجهة n8n: الـ Canvas والـ Nodes',
  'أول Workflow: Manual Trigger وSet node',
  'فهم البيانات: Items وصيغة JSON',
  'التعبيرات Expressions: كيف تستدعي بيانات من node سابقة',
  'الـ Triggers: Schedule وWebhook',
  'HTTP Request node: الاتصال بأي API',
  'الـ Credentials: ربط حساباتك بأمان',
  'التحكم بالمسار: IF وSwitch',
  'التكرار والدمج: Loop Over Items وMerge',
  'Code node: JavaScript لتحويل البيانات',
  'معالجة الأخطاء وError Trigger',
  'التعامل مع Google Sheets',
  'إرسال واستقبال الإيميلات مع Gmail',
  'بناء بوت تيليجرام بسيط',
  'ما هو الـ AI Agent',
  'الـ AI Agent node وربطه بنموذج لغوي Chat Model',
  'الـ Memory: ذاكرة المحادثة للوكيل',
  'الـ Tools: إعطاء الوكيل أدوات',
  'كتابة System Prompt فعّال للوكيل',
  'Structured Output: مخرجات JSON من الذكاء الاصطناعي',
  'مفهوم RAG وقواعد المعرفة',
  'بناء RAG: المستندات والـ Embeddings والـ Vector Store',
  'بوت دعم عملاء يعتمد على RAG',
  'أتمتة المحتوى: توليد منشورات وجدولتها',
  'وكيل يلخص الإيميلات ويكتب الردود',
  'ربط عدة وكلاء معا Multi-agent',
  'أفضل الممارسات: الأمان والمراقبة',
  'نشر مشروعك وتسعير خدمات الأتمتة'
];

// نشيل أي مسافات زايدة من أسماء أعمدة الـ Sheet
const rows = $input.all().map(i =>
  Object.fromEntries(Object.entries(i.json).map(([k, v]) => [String(k).trim(), v])));
const doneRows = rows.filter(r => r.youtube_url);

// رقم الدرس = عدد الدروس المنشورة فعلا + 1
const n = doneRows.length + 1;
if (n > LESSONS.length) throw new Error('الكورس خلص: تم نشر كل الدروس (' + LESSONS.length + ')');

// رابط الدرس السابق (آخر صف فيه رابط حقيقي)
const last = doneRows[doneRows.length - 1];
const prevUrl = last && /^https?:\/\//.test(String(last.youtube_url)) ? String(last.youtube_url) : '';

const title = LESSONS[n - 1];
const prev = n > 1 ? LESSONS[n - 2] : 'لا يوجد (هذا أول درس)';
const next = n < LESSONS.length ? LESSONS[n] : 'لا يوجد (هذا آخر درس)';

const system = 'أنت مدرّب أتمتة محترف تقدّم كورسا بالعربية على يوتيوب شورتس. تكتب معلومات دقيقة فقط، ولا تخترع ميزات أو أسماء أو أرقام. ترجع JSON صالح فقط بدون أي نص إضافي.';

const user = `أنت تقدّم كورسا قصيرا بعنوان: تعلّم أتمتة الذكاء الاصطناعي مع n8n من الصفر.
هذا الدرس رقم ${n} من ${LESSONS.length}: ${title}
الدرس السابق: ${prev}
الدرس القادم: ${next}

اكتب سكربت فيديو قصير مدته 35 إلى 45 ثانية بالعربية الفصحى المبسطة يشرح فكرة واحدة فقط من هذا الدرس بوضوح.
الشروط:
- المشهد الأول: ترحيب سريع برقم الدرس واسمه، مع سؤال أو مشكلة تشدّ المشاهد.
- من 6 إلى 7 مشاهد، كل مشهد جملة واحدة لا تزيد عن 14 كلمة.
- اشرح الفكرة بمثال عملي بسيط واحد على الأقل.
- المشهد الأخير: ملخص بجملة واحدة، ثم تشويق للدرس القادم، ثم دعوة للمتابعة.
- معلومات دقيقة فقط عن n8n. لا تذكر أرقام إصدارات أو أسماء حقول أو أزرار إذا لم تكن متأكدا منها.
- اكتب المصطلحات التقنية بحروف عربية مفهومة عند النطق (مثل: ووركفلو، نود، ويب هوك، إيه بي آي)، وتبقى كلمة n8n كما هي.
- keywords: كلمتان أو ثلاث بالإنجليزية لمشهد بصري تقني عام، اختر من أمثلة مثل: "typing on laptop", "code on screen", "data network", "server room", "analytics dashboard", "robot arm", "artificial intelligence", "cloud technology", "smartphone app", "computer circuit", "gears machine", "business meeting".
- description: جملتان عن محتوى الدرس.
- tags: من 4 إلى 6 كلمات عربية.

صيغة الإخراج JSON فقط:
{"description":"","tags":[""],"scenes":[{"text":"","keywords":""}]}`;

return [{ json: {
  lessonNo: n, lessonTitle: title, prevTitle: prev, prevUrl, model: MODEL,
  groqBody: {
    systemInstruction: { parts: [{ text: system }] },
    contents: [{ role: 'user', parts: [{ text: user }] }],
    generationConfig: { temperature: 0.7, maxOutputTokens: 8000, responseMimeType: 'application/json' }
  }
}}];

const parts = $input.first().json.candidates?.[0]?.content?.parts || [];
const raw = parts.map(p => p.text || '').join('').replace(/```json|```/g, '').trim();
let d;
try { d = JSON.parse(raw); }
catch (e) { throw new Error('Gemini رجّع JSON غير صالح: ' + String(raw).slice(0, 200)); }
if (!Array.isArray(d.scenes) || d.scenes.length < 4) throw new Error('عدد المشاهد غير كافي');

const L = $('Build Prompt').first().json;

// رابط الدرس السابق بالوصف
const prevLine = (L.lessonNo > 1 && L.prevUrl)
  ? '\n\nالدرس السابق: ' + L.prevTitle + '\n' + L.prevUrl
  : '';

const meta = {
  topic: L.lessonTitle,
  title: ('كورس n8n | الدرس ' + L.lessonNo + ': ' + L.lessonTitle).slice(0, 95),
  description: String(d.description || '') +
    '\n\nالدرس ' + L.lessonNo + ' من كورس تعلّم أتمتة الذكاء الاصطناعي مع n8n من الصفر.' +
    prevLine +
    '\n\n#Shorts #n8n #أتمتة #ذكاء_اصطناعي',
  tags: ['n8n', 'أتمتة', 'ai automation', 'تعلم n8n']
    .concat(Array.isArray(d.tags) ? d.tags : []).slice(0, 10).join(',')
};

const wc = t => String(t).trim().split(/\s+/).length;

let scenes = d.scenes.slice(0, 9).map(s => ({
  text: String(s.text),
  keywords: String(s.keywords || 'code on screen')
}));

const MAX_WORDS = 105;
let total = scenes.reduce((a, s) => a + wc(s.text), 0);
while (total > MAX_WORDS && scenes.length > 4) {
  const removed = scenes.splice(scenes.length - 2, 1)[0];
  total -= wc(removed.text);
}

return scenes.map((s, i) => ({
  json: { ...meta, idx: i, text: s.text, keywords: s.keywords }
}));

const VOICE = 'ar-SA-HamedNeural';   // غيّر الصوت من هون إذا بدك (مثلا ar-EG-ShakirNeural)

const scenesIn = $('Parse Script').all().map(i => i.json);
const pex = $input.all();

// مرشحين لكل مشهد (id + رابط)
function candidates(res) {
  const hits = (res.json && res.json.hits) || [];
  const out = [];
  for (const h of hits.slice(0, 5)) {
    const v = h.videos || {};
    const u = (v.medium && v.medium.url) || (v.large && v.large.url) || (v.small && v.small.url);
    if (u) out.push({ id: h.id, url: u });
  }
  return out;
}

// اختيار مقطع مختلف لكل مشهد قدر الإمكان
const used = new Set();
const clips = pex.map(res => {
  const list = candidates(res);
  const fresh = list.filter(c => !used.has(c.id));
  const pool = fresh.length ? fresh : list;
  if (!pool.length) return null;
  const c = pool[Math.floor(Math.random() * pool.length)];
  used.add(c.id);
  return c.url;
});

const fallback = clips.find(Boolean);
if (!fallback) throw new Error('ما لقيت أي مقطع من Pixabay');

const scenes = scenesIn.map((s, i) => ({
  elements: [
    { type: 'video', src: clips[i] || fallback, resize: 'cover', duration: -2, loop: -1, muted: true },
    { type: 'voice', text: s.text, voice: VOICE, model: 'azure' }
  ]
}));

const movie = {
  resolution: 'custom',
  width: 1080,
  height: 1920,
  quality: 'high',
  scenes,
  elements: [
    { type: 'subtitles', language: 'ar', settings: { style: 'classic', position: 'mid-bottom-center', 'font-size': 80 } }
  ]
};

const m = scenesIn[0];
return [{ json: { movie, topic: m.topic, title: m.title, description: m.description, tags: m.tags } }];

const m = $input.first().json.movie || {};
if (m.status === 'error') throw new Error('JSON2Video error: ' + (m.message || 'unknown'));
if ($runIndex > 25) throw new Error('انتهت مهلة الرندر');
return [{ json: { status: m.status, url: m.url || null } }];

const m = $('Build Movie').first().json;
const yt = $input.first().json;
const id = yt.id || yt.videoId || yt.uploadId;
return [{ json: {
  topic: m.topic,
  title: m.title,
  youtube_url: id ? 'https://youtu.be/' + id : 'uploaded-id-unknown',
  date: new Date().toISOString().slice(0, 10)
}}];

const m = $('Build Movie').first().json;
return [{ json: {
  job_id: 'j' + Date.now(),
  video_url: $('Check Status').last().json.url,
  title: m.title,
  description: m.description,
  tags: m.tags,
  topic: m.topic,
  privacy: $('Config').first().json.privacy
}}];

